<?php declare(strict_types=1);require_once __DIR__.'/includes/store.php';$pageTitle='Create account';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_is_valid($_POST['csrf_token']??null)){http_response_code(419);exit('Invalid form token.');}$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter your name and a valid email.';if(strlen($password)<12)$errors[]='Use a password of at least 12 characters.';if($password!==$confirm)$errors[]='Passwords do not match.';if(!$errors){try{$s=$pdo->prepare("INSERT INTO users(full_name,email,phone,password_hash,role,status) VALUES(?,?,?,?,'customer','active')");$s->execute([$name,$email,$phone?:null,password_hash($password,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)$pdo->lastInsertId();redirect('profile.php');}catch(PDOException $e){$errors[]=$e->getCode()==='23000'?'An account with that email already exists.':'Could not create account. Run the Stage 4 migration if required.';}}}require __DIR__.'/includes/header.php';?><section class="container py-5" style="max-width:680px"><h1 class="h2">Create your account</h1><p class="text-secondary">Track orders and keep your details together.</p><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-label">Full name</label><input class="form-control mb-3" name="full_name" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Phone</label><input class="form-control mb-3" name="phone"><label class="form-label">Password (12+ characters)</label><input class="form-control mb-3" type="password" name="password" minlength="12" required><label class="form-label">Confirm password</label><input class="form-control mb-3" type="password" name="confirm_password" minlength="12" required><button class="btn btn-primary">Register</button><p class="mt-3 mb-0">Already registered? <a href="login.php">Log in</a></p></form></section><?php require __DIR__.'/includes/footer.php';?>